INSERT INTO feature VALUES('dead-weight-report','workflow','Dead weight by reverse references',NULL,'implemented','ordinary',NULL,'Each night `report:dead-weight` reads the compiler''s evidence records of the newest landed merge group and keeps one `refactor(<crate>): dead weight` issue for each crate: the items that no code outside tests names, and the exported items that no other crate names. It leaves out an item that a commit touched in the last 14 days and each item that `.config/dead-weight/kept.txt` keeps. No figure is a gate.',NULL,'.config/dead-weight/cases.json',NULL,'#2891');
